990	// interactiveUpdateInputs turns the interactive form's seed and edited values
991	// into update inputs, marking a field changed only when the user actually edited
992	// it away from the seed. The body in particular must not be re-sent when
993	// unedited: its seed may be empty (the current body failed to load) or
994	// whitespace-trimmed, and re-PATCHing it would erase or rewrite the live
995	// collaborative document.
996	func interactiveUpdateInputs(seed, edited trailUpdateEdits) trailUpdateInputs {
997		return trailUpdateInputs{
998			Status:        edited.status,
999			StatusChanged: edited.status != seed.status,
1000			Title:         edited.title,
1001			TitleChanged:  edited.title != seed.title,
1002			Body:          edited.body,
1003			BodyChanged:   edited.body != seed.body,
1004		}
1005	}
