1207	func patchTrail(ctx context.Context, client *api.Client, path string, req api.TrailUpdateRequest) error {
1208		resp, err := client.Patch(ctx, path, req)
1209		if err != nil {
1210			return fmt.Errorf("failed to update trail: %w", err)
1211		}
1212		defer resp.Body.Close()
1213		if err := checkTrailResponse(resp); err != nil {
1214			return err
1215		}
1216		var updateResp api.TrailUpdateResponse
1217		if err := api.DecodeJSON(resp, &updateResp); err != nil {
1218			return fmt.Errorf("failed to decode update response: %w", err)
1219		}
1220		return nil
1221	}
