1236	// buildTrailUpdateRequest constructs a PATCH request body from the current trail and the requested changes.
1237	func buildTrailUpdateRequest(current *api.TrailResource, inputs trailUpdateInputs) api.TrailUpdateRequest {
1238		var req api.TrailUpdateRequest
1239	
1240		if inputs.StatusChanged {
1241			req.Status = &inputs.Status
1242		}
1243		if inputs.TitleChanged {
1244			req.Title = &inputs.Title
1245		}
1246		if inputs.BodyChanged {
1247			req.Body = &inputs.Body
1248		}
1249	
1250		// Handle label changes: merge adds, remove removes.
1251		if len(inputs.LabelAdd) > 0 || len(inputs.LabelRemove) > 0 {
1252			labels := make([]string, 0, len(current.Labels)+len(inputs.LabelAdd))
1253			labels = append(labels, current.Labels...)
1254			for _, l := range inputs.LabelAdd {
1255				found := false
1256				for _, existing := range labels {
1257					if existing == l {
1258						found = true
1259						break
1260					}
1261				}
1262				if !found {
1263					labels = append(labels, l)
1264				}
1265			}
1266			for _, l := range inputs.LabelRemove {
1267				for i, existing := range labels {
1268					if existing == l {
1269						labels = append(labels[:i], labels[i+1:]...)
1270						break
1271					}
1272				}
1273			}
1274			req.Labels = &labels
1275		}
1276	
1277		return req
1278	}
